import { describe, expect, it } from 'vitest'
import en from './en.json'
import ptBR from './pt-BR.json'
// Generated by ts-rs from the Rust `JobRequest` enum.
import jobRequest from '../types/JobRequest.ts?raw'

const kinds = [...jobRequest.matchAll(/"type": "(\w+)"/g)].map((m) => m[1] ?? '')

describe('job names', () => {
  it('cover every operation of the backend in both languages', () => {
    expect(kinds.length).toBeGreaterThan(30)
    for (const messages of [ptBR, en]) {
      const names = messages.jobs.kinds as Record<string, string>
      expect(kinds.filter((kind) => !names[kind])).toEqual([])
    }
  })
})
